(1, 1, '2026-09-25', 148, 89, 107.00, 'rbs', 83.30, 164.00, 31.0, 79.40, 'Losartan 50mg #30, Amlodipine 5mg #30', 30, 'poor', 'Routine BP checkup and maintenance medication refill. No current chest pain or shortness of breath.', 'Dispensed 30-day maintenance medications. Advised to continue low-sodium diet and return in 1 month.', '2026-10-25', 2, '2026-10-28 15:25:29'),
(2, 1, '2026-10-19', 130, 77, 95.00, 'rbs', 81.30, 164.00, 30.2, 96.60, 'Losartan 50mg #30, Amlodipine 5mg #30', 30, 'poor', 'Reports occasional morning dizziness and nape heaviness after skipping medication.', 'Counselled on lifestyle modifications: reduced salt, avoid salty processed food, daily physical activity. Return in 30 days.', '2026-10-21', 2, '2026-10-28 15:25:29'),
(3, 2, '2026-09-20', 116, 71, 146.00, 'fbs', 82.10, 171.00, 28.1, 97.70, 'Metformin 500mg #60', 30, 'good', 'Reports occasional morning dizziness and nape heaviness after skipping medication.', 'Counselled on lifestyle modifications: reduced salt, avoid salty processed food, daily physical activity. Return in 30 days.', '2026-10-20', 2, '2026-10-28 15:25:29'),
